mapper.select:
SELECT count(*)
FROM forms
WHERE space_id = #{spaceId} AND event_id = #{eventId}

SELECT id AS form_id, accepting_applications
FROM forms
WHERE space_id = #{spaceId} AND event_id = #{eventId}

SELECT id AS field_id, kind, system_key, label, position,
  answer_type, required, description, config::text AS config,
  show_when::text AS show_when, hidden,
  preset_key, preset_state::text AS preset_state
FROM fields
WHERE id = #{fieldId}
  AND form_id = #{formId}
  AND space_id = #{spaceId}
  AND event_id = #{eventId}

SELECT count(*)
FROM fields
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND form_id = #{formId}

SELECT count(*)
FROM applications
WHERE space_id = #{spaceId}
  AND event_id = #{eventId}
  AND form_id = #{formId}
  AND status = 'SUBMITTED'

SELECT COALESCE(MAX(position), -1)
FROM fields
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND form_id = #{formId}
